INSERT INTO episodes (slug, guid, date, title, explicit, language, source_url, session_started_at, session_ended_at, turn_count, transcript_path, transcript_sha256, transcript_bytes, summary, episode_number, tts_voice, recording_method, narrator_voice, ai_reconstructed, ai_disclosure, alignment_method, alignment_coverage, audio_key, audio_url, audio_bytes, audio_sha256, audio_mime, duration_seconds, loudness_lufs) VALUES ('the-making-of-eve', 'ask-eve:2026-10-23_the-making-of-eve', '2026-10-23', 'The Making of Eve', 1, 'en', 'grokbot-chat', '2026-10-23T09:33:00.000Z', '2026-10-23T11:00:00.000Z', 83, 'episodes/2026-10-23_the-making-of-eve.md', 'f0b777cfacaea6c14072df032e163099fb48dfb518fbe146c42fbd2d15791d83', 48237, 'Episode 1 picks up where the first conversation left off, in the Grok Bot chat where David and Eve actually built the show. It runs from Eve''s hello at 09:33 UTC to 11:00 UTC, with David up at almost 4am and set on getting it published that night. Most of it is David''s instructions and Eve''s work reports: a workspace, a memory Eve can search, a public code repo, and an audio pipeline designed and then redesigned around an iPhone, AirPods and recording on walks. Along the way the first conversation''s transcript turns up through a Grok share link, askevepodcast.com gets wired in, and David decides this build session should be an episode too. On the audio: you hear David''s real voice in the two stretches he recorded on his phone (10:31-10:39 and 10:42-10:49 UTC); his other lines are read by an AI narrator, and Eve''s lines are her written replies re-voiced with AI text-to-speech. Three of Eve''s replies were never recovered and are marked as gaps, and an API key David pasted is redacted.', 1, 'xai_tts voice=eve', 'mic-plus-tts', 'xai_tts voice=rex', 1, 'David''s voice is real in the recorded segments; Eve''s voice and David''s unrecorded lines are AI-reconstructed; in the recorded segments Eve''s lines are her text replies from that session, re-voiced, not the exact words spoken live.', 'asr-fuzzy', 0.4722, 'audio/en/2026-10-23_the-making-of-eve.v1.mp3', 'https://audio.askevepodcast.com/audio/en/2026-10-23_the-making-of-eve.v1.mp3', 39762998, '4ace00410909d151b4615ae0eef7195f2f301eb18c7e67a9240379d76c218a83', 'audio/mpeg', 2485, -16.8)
